// Native-only storage ABI. Actual addresses are written and consumed on the
// GPU; JavaScript sees only the browser's opaque resource objects. A logical
// renderer buffer can exceed the browser's per-shared-allocation size limit.
template<class T> struct OmwPaged {
    const unsigned long long* pages;
    T* direct;
    unsigned long long first;
    __device__ OmwPaged(const unsigned long long* table):pages(table),direct(nullptr),first(0) {}
    __device__ OmwPaged(T* pointer):pages(nullptr),direct(pointer),first(0) {}
    template<class U> __device__ OmwPaged(const OmwPaged<U>& other):pages(other.pages),direct(other.direct),first(other.first) {}
    __device__ T& operator[](unsigned long long index) const {
        index+=first;
        if(direct)return direct[index];
        unsigned long long bytes=index*sizeof(T);
        return *reinterpret_cast<T*>(pages[bytes>>26]+(bytes&67108863ull));
    }
    __device__ OmwPaged operator+(unsigned long long offset) const {
        OmwPaged result=*this;result.first+=offset;return result;
    }
};

// Local-map exploration mask. Inputs are saved RGBA8 pixels plus brush history.
// One thread owns one pixel; each brush applies the engine's minimum-alpha rule.
// Brush records: center X, center Y, squared exploration radius, in texel units.
__global__ void generate_fog_map(const unsigned long long* omw_pages_blocks,const unsigned long long* omw_pages_pixels,
                                unsigned int width,unsigned int height,unsigned int block_offset,unsigned int pixel_offset) {
OmwPaged<const unsigned int> blocks(omw_pages_blocks);
OmwPaged<unsigned int> pixels(omw_pages_pixels);

    unsigned int i=(blockIdx.x+blockIdx.y*gridDim.x)*blockDim.x+threadIdx.x;
    if(i>=width*height)return;
    unsigned int brush_count=blocks[block_offset],saved=blocks[block_offset+1u+i];
    unsigned int brushes=block_offset+1u+width*height;
    unsigned int alpha=saved>>24u;
    float x=(float)(i%width),y=(float)(i/width);
    for(unsigned int b=0;b<brush_count;b++) {
        float dx=x-__uint_as_float(blocks[brushes+b*3u]),dy=y-__uint_as_float(blocks[brushes+b*3u+1u]);
        float fraction=fminf(1.0f,fmaxf(0.0f,(dx*dx+dy*dy)/__uint_as_float(blocks[brushes+b*3u+2u])));
        unsigned int candidate=(unsigned int)(fraction*255.0f);
        if(candidate<alpha)alpha=candidate;
    }
    pixels[pixel_offset+i]=brush_count==0u?saved:alpha<<24u;
}
